export const uid=()=>globalThis.crypto?.randomUUID?.()||`id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
export const clone=v=>structuredClone(v);
export const animatable=['x','y','rotation','scaleX','scaleY','opacity','fill','stroke','strokeWidth','nodes','mesh','shadowX','shadowY','shadowBlur','shadowOpacity','shadowColor'];
export function object(type,props={}){return {id:uid(),type,name:type[0].toUpperCase()+type.slice(1),visible:true,locked:false,x:0,y:0,width:180,height:140,anchorX:0,anchorY:0,scaleX:1,scaleY:1,rotation:0,opacity:1,fill:'#a8adb5',stroke:'#282734',strokeWidth:0,font:'sans-serif',fontSize:64,align:'left',text:'Hello!',radius:0,nodes:[],closed:false,children:[],tracks:{},shadowEnabled:false,shadowX:12,shadowY:12,shadowBlur:12,shadowOpacity:.35,shadowColor:'#000000',...props};}
export function project(){return {version:1,id:uid(),name:'Untitled animation',width:1280,height:720,fps:24,duration:6,background:'#ffffff',layers:[],audio:null};}
export function walk(nodes,fn,parent=null){nodes.forEach(n=>{fn(n,parent);walk(n.children||[],fn,n);});}
export function find(p,id){let found;walk(p.layers,n=>{if(n.id===id)found=n;});return found;}
export function locate(p,id){let result;const visit=(list,parent)=>list.forEach((n,index)=>{if(n.id===id)result={list,index,node:n,parent};visit(n.children||[],n);});visit(p.layers,null);return result;}
export function isLocked(p,id){let entry=locate(p,id);while(entry){if(entry.node.locked)return true;entry=entry.parent?locate(p,entry.parent.id):null;}return false;}
export function selectionRoots(p,ids){const set=new Set(ids),out=[];const visit=list=>list.forEach(n=>{if(set.has(n.id))out.push(n);else visit(n.children||[]);});visit(p.layers);return out;}
export function validate(p){if(!p||p.version!==1||!Array.isArray(p.layers))throw Error('This is not a Poppy project.');for(const k of ['width','height','fps','duration'])if(!Number.isFinite(p[k])||p[k]<=0)throw Error(`Invalid composition ${k}.`);if(p.width>4096||p.height>4096||p.duration>600||![12,24,25,30,60].includes(p.fps))throw Error('Composition exceeds supported limits (4096px, 10 minutes).');const ids=new Set();let count=0;const check=(list,depth)=>{if(depth>30)throw Error('Too many nested groups.');for(const n of list){if(++count>3000||!n.id||ids.has(n.id)||!['rectangle','ellipse','path','freehand','text','group','image'].includes(n.type))throw Error('Invalid scene object.');ids.add(n.id);for(const k of ['x','y','width','height','anchorX','anchorY','scaleX','scaleY','rotation','opacity','strokeWidth'])if(!Number.isFinite(n[k]))throw Error(`Invalid ${k}.`);for(const [prop,track] of Object.entries(n.tracks||{})){if(!animatable.includes(prop)||!Array.isArray(track))throw Error('Invalid animation track.');for(const key of track)if(!Number.isFinite(key.time)||key.time<0||key.time>p.duration||(typeof key.value==='number'&&!Number.isFinite(key.value)))throw Error('Invalid keyframe.');track.sort((a,b)=>a.time-b.time);}check(n.children||[],depth+1);}};check(p.layers,0);return p;}
export class History{constructor(get,set,onChange){this.get=get;this.set=set;this.onChange=onChange;this.undoStack=[];this.redoStack=[];this.before=null;}begin(){if(!this.before)this.before=clone(this.get());}commit(label='Edit'){if(!this.before)return;const after=clone(this.get());if(JSON.stringify(this.before)!==JSON.stringify(after)){this.undoStack.push({before:this.before,after,label});if(this.undoStack.length>60)this.undoStack.shift();this.redoStack=[];this.onChange?.();}this.before=null;}cancel(){if(this.before)this.set(this.before);this.before=null;}run(label,fn){this.begin();try{fn();this.commit(label);}catch(e){this.cancel();throw e;}}undo(){const e=this.undoStack.pop();if(e){this.redoStack.push(e);this.set(clone(e.before));this.onChange?.();}}redo(){const e=this.redoStack.pop();if(e){this.undoStack.push(e);this.set(clone(e.after));this.onChange?.();}}clear(){this.undoStack=[];this.redoStack=[];this.before=null;}}
